require_once __DIR__.'/../lib/helpers.php';require_once __DIR__.'/../lib/admin.php';send_cors_headers();$context=require_admin('content.manage');$db=get_db();$method=$_SERVER['REQUEST_METHOD']??'GET';if($method==='GET'){$type=trim((string)($_GET['type']??''));$stmt=$db->prepare('SELECT * FROM cms_entries WHERE (:type="" OR entry_type=:type) ORDER BY updated_at DESC,created_at DESC LIMIT 300');$stmt->execute(['type'=>$type]);json_response(200,['success'=>true,'entries'=>$stmt->fetchAll()]);}if(in_array($method,['POST','PATCH'],true)){$body=get_json_body();$type=trim((string)($body['entry_type']??''));$title=trim((string)($body['title']??''));$slug=strtolower(trim(preg_replace('/[^a-z0-9]+/','-',strtolower((string)($body['slug']??$title))),'-'));$content=$body['content']??null;if(!in_array($type,['page','banner','blog','announcement','faq'],true)||mb_strlen($title)<3||$slug===''||!is_array($content))json_response(422,['success'=>false,'message'=>'Content type, title, slug and structured content are required.']);$status=in_array($body['status']??'draft',['draft','published','archived'],true)?$body['status']:'draft';if($method==='POST'){$id=uuid_string();$db->prepare('INSERT INTO cms_entries (id,entry_type,slug,title,content_json,status,starts_at,ends_at,created_by,created_at,updated_at,published_at) VALUES (:id,:type,:slug,:title,:content,:status,:starts,:ends,:admin,UTC_TIMESTAMP(),UTC_TIMESTAMP(),IF(:status="published",UTC_TIMESTAMP(),NULL))')->execute(['id'=>$id,'type'=>$type,'slug'=>$slug,'title'=>$title,'content'=>json_encode($content,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),'status'=>$status,'starts'=>$body['starts_at']??null,'ends'=>$body['ends_at']??null,'admin'=>$context['admin']['id']]);json_response(201,['success'=>true,'message'=>'Content created.','entry_id'=>$id]);}$id=trim((string)($body['id']??''));$db->prepare('UPDATE cms_entries SET entry_type=:type,slug=:slug,title=:title,content_json=:content,status=:status,starts_at=:starts,ends_at=:ends,updated_at=UTC_TIMESTAMP(),published_at=IF(:status="published",COALESCE(published_at,UTC_TIMESTAMP()),published_at) WHERE id=:id')->execute(['type'=>$type,'slug'=>$slug,'title'=>$title,'content'=>json_encode($content,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),'status'=>$status,'starts'=>$body['starts_at']??null,'ends'=>$body['ends_at']??null,'id'=>$id]);json_response(200,['success'=>true,'message'=>'Content updated.']);}json_response(405,['success'=>false,'message'=>'Method not allowed.']);
